// Picks the next DUE tiktok item from Nathan's queue.
// A TikTok post is impossible without a video, so items lacking videoUrl are
// skipped. There is no fallback: nothing queued means nothing posted.
const fs = require('fs');

const QUEUE_PATH =
  $env.TS_CONTENT_QUEUE ||
  'C:\\work\\OneTradingSocial\\Website\\automation\\n8n\\content-queue.json';

let queue;
try {
  queue = JSON.parse(fs.readFileSync(QUEUE_PATH, 'utf8'));
} catch (err) {
  throw new Error('Cannot read the content queue at ' + QUEUE_PATH + ': ' + err.message);
}

const now = Date.now();
const due = (queue.items || [])
  .filter(
    (i) =>
      i.platform === 'tiktok' &&
      i.status === 'pending' &&
      i.videoUrl &&
      (!i.scheduledFor || Date.parse(i.scheduledFor) <= now)
  )
  .sort((a, b) => {
    const ta = a.scheduledFor ? Date.parse(a.scheduledFor) : 0;
    const tb = b.scheduledFor ? Date.parse(b.scheduledFor) : 0;
    return ta - tb;
  });

if (due.length === 0) {
  return [
    {
      json: {
        found: false,
        reason: 'No tiktok item is pending, due, and carrying a videoUrl.'
      }
    }
  ];
}

const item = due[0];
return [
  {
    json: {
      found: true,
      source: 'queue',
      itemId: item.id,
      videoUrl: item.videoUrl,
      caption: item.text || ''
    }
  }
];

// TikTok access tokens live 24h; refresh tokens live 365 days and ROTATE on
// every refresh. The current refresh token is kept in workflow static data so
// the rotation survives restarts. TIKTOK_REFRESH_TOKEN seeds it on first run.
const store = $getWorkflowStaticData('global');
const refreshToken = store.tiktokRefreshToken || $env.TIKTOK_REFRESH_TOKEN;

if (!refreshToken) {
  throw new Error(
    'No TikTok refresh token. Set TIKTOK_REFRESH_TOKEN in .env after completing the OAuth consent flow (see README step 6).'
  );
}

return [{ json: { refreshToken } }];

// Persist the rotated refresh token immediately — if this run later fails, the
// old refresh token is already dead and only the new one will work.
const res = $json;

if (res.error) {
  throw new Error(
    'TikTok token refresh failed: ' + res.error + ' — ' + (res.error_description || '')
  );
}
if (!res.access_token) {
  throw new Error('TikTok token refresh returned no access_token: ' + JSON.stringify(res).slice(0, 300));
}

const store = $getWorkflowStaticData('global');
if (res.refresh_token) {
  store.tiktokRefreshToken = res.refresh_token;
  store.tiktokRefreshedAt = new Date().toISOString();
}

return [
  {
    json: {
      accessToken: res.access_token,
      openId: res.open_id || '',
      expiresIn: res.expires_in || 0
    }
  }
];

// Chooses the endpoint and assembles the publish payload.
//
// TIKTOK_MODE:
//   inbox  (default) — uploads to the creator's TikTok inbox as a draft they
//                      finish and post by hand. Needs only the video.upload
//                      scope and works WITHOUT app audit.
//   direct           — publishes straight to the account. Needs video.publish
//                      AND an audited app, otherwise TikTok forces SELF_ONLY.
const creator = $json;

if (creator.error && creator.error.code && creator.error.code !== 'ok') {
  throw new Error(
    'TikTok creator_info failed: ' +
      creator.error.code +
      ' — ' +
      (creator.error.message || '')
  );
}

const info = creator.data || {};
const prep = $('Prepare Post').first().json;
const mode = ($env.TIKTOK_MODE || 'inbox').toLowerCase();

let endpoint;
let body;

if (mode === 'direct') {
  // privacy_level MUST be one of the options TikTok returned for this creator.
  // Unaudited apps only ever get SELF_ONLY, so never hardcode PUBLIC.
  const allowed = info.privacy_level_options || [];
  const wanted = $env.TIKTOK_PRIVACY_LEVEL || '';
  const privacy = allowed.includes(wanted) ? wanted : allowed[0];

  if (!privacy) {
    throw new Error(
      'TikTok returned no privacy_level_options — the account cannot be posted to right now.'
    );
  }

  endpoint = 'https://open.tiktokapis.com/v2/post/publish/video/init/';
  body = {
    post_info: {
      title: prep.caption,
      privacy_level: privacy,
      disable_duet: false,
      disable_comment: false,
      disable_stitch: false,
      video_cover_timestamp_ms: 1000
    },
    source_info: {
      source: 'PULL_FROM_URL',
      video_url: prep.videoUrl
    }
  };
} else {
  // Draft-to-inbox: no post_info block is accepted here. The caption is carried
  // through so it can be logged and copy-pasted when finishing the draft.
  endpoint = 'https://open.tiktokapis.com/v2/post/publish/inbox/video/init/';
  body = {
    source_info: {
      source: 'PULL_FROM_URL',
      video_url: prep.videoUrl
    }
  };
}

return [
  {
    json: {
      mode,
      endpoint,
      body,
      caption: prep.caption,
      creatorNickname: info.creator_nickname || ''
    }
  }
];

// Marks the queue item posted and appends to the post log.
const fs = require('fs');
const path = require('path');

const QUEUE_PATH =
  $env.TS_CONTENT_QUEUE ||
  'C:\\work\\OneTradingSocial\\Website\\automation\\n8n\\content-queue.json';
const LOG_PATH = path.join(path.dirname(QUEUE_PATH), 'post-log.jsonl');

const prep = $('Prepare Post').first().json;
const publish = $('Publish to TikTok').first().json;
const request = $('Build Publish Request').first().json;
const status = $json;

if (publish.error && publish.error.code && publish.error.code !== 'ok') {
  throw new Error(
    'TikTok publish failed: ' + publish.error.code + ' — ' + (publish.error.message || '')
  );
}

const entry = {
  at: new Date().toISOString(),
  platform: 'tiktok',
  mode: request.mode,
  source: prep.source,
  itemId: prep.itemId || null,
  publishId: (publish.data && publish.data.publish_id) || null,
  status: (status.data && status.data.status) || 'UNKNOWN',
  failReason: (status.data && status.data.fail_reason) || null,
  caption: prep.caption
};

if (prep.itemId) {
  try {
    const queue = JSON.parse(fs.readFileSync(QUEUE_PATH, 'utf8'));
    const target = (queue.items || []).find((i) => i.id === prep.itemId);
    if (target) {
      target.status = 'posted';
      target.postedAt = entry.at;
      fs.writeFileSync(QUEUE_PATH, JSON.stringify(queue, null, 2), 'utf8');
      entry.queueUpdated = true;
    }
  } catch (err) {
    entry.queueError = String(err.message || err);
  }
}

try {
  fs.appendFileSync(LOG_PATH, JSON.stringify(entry) + '\n', 'utf8');
} catch (err) {
  // The post already went out — never fail the run on logging.
}

return [{ json: entry }];
